"""gen_ascii_model.py <weights.json> <out collation_model.py>: the ASCII part of the utf8mb4_0900_ai_ci weights (from dump_weights.py), as the small Python model the
verifiers in code/test/diff use to order and compare texts (they are independent of the engine's own table)."""
import json
import sys

weights = json.load(open(sys.argv[1]))
table = {}
for cp in range(1, 128):
    hx = weights[str(cp)]
    table[chr(cp)] = tuple(int(hx[i:i + 4], 16) for i in range(0, len(hx), 4))

lines = [
    '"""utf8mb4_0900_ai_ci (MySQL 8.4\'s default collation) for ASCII texts: generated by code/test/collation/gen_ascii_model.py from the weights of a real MySQL.',
    '',
    'Texts compare by their primary weights, letter by letter, with NO PAD (a space at the end counts); a character without weights is ignored.',
    '"""',
    '',
    'WEIGHTS = {',
]
for ch, w in table.items():
    lines.append(f"    {ch!r}: {w!r},")
lines += [
    '}',
    '',
    '',
    'def key(text):',
    '    """The tuple of weights of a text: equal tuples are equal texts, and tuples sort the way the texts do."""',
    '    out = []',
    '    for ch in text:',
    '        out.extend(WEIGHTS[ch])',
    '    return tuple(out)',
    '',
    '',
    'def compare(a, b):',
    '    x, y = key(a), key(b)',
    '    return (x > y) - (x < y)',
    '',
]
open(sys.argv[2], "w", encoding="utf-8").write("\n".join(lines))
